{#- ------ Macros Start ----- -#}

{%- macro html_output(html_title, source_datum, list_wrapper , markdown, rich ) -%}
  {# Handle Drupal-style objects with a "value" property #}
 {% set list_wrapper = list_wrapper|default("p") %}
 {% set markdown = markdown|default(false) %}
 {% set rich = rich|default(false) %}

  {%- if source_datum is iterable and 'value' in source_datum|keys -%}
    {%- set source_datum = source_datum.value -%}
  {%- endif -%}
 
  {# -- Macro note: if markdown is selected no wrapper will be used -#}
  {%- if source_datum and source_datum|length > 0 -%}
  <div class="row border-1 mx-1 border-bottom">
    <div class="col-3 fw-light">
    {%- if html_title|length > 0 -%}
     <{{ list_wrapper }}>{{ html_title }}</{{ list_wrapper }}>
    {%- endif -%}
    </div>
    <div class="col-9 fw-light">
    {%- if source_datum is iterable -%}
      {%- for source_data in source_datum -%}
        {%- if markdown and source_data is instanceof('scalar') -%}
          {{ source_data|markdown_2_html }}
        {%- else -%}
          {%- if rich and source_data is instanceof('scalar')-%}
            <{{ list_wrapper }}>{{ source_data|raw }}</{{ list_wrapper }}>
          {%- elseif source_data is instanceof('scalar') -%}
            <{{ list_wrapper }}>{{ source_data|striptags }}</{{ list_wrapper }}>
          {%- endif -%}
        {%- endif -%}
      {%- endfor -%}
    {%- else -%}
      {%- if markdown -%}
        {{ source_datum|markdown_2_html }}
      {%- else -%}
        {%- if rich -%}
          {%- if list_wrapper|length > 0 -%}
            <{{ list_wrapper }}>{{ source_datum|raw }}</{{ list_wrapper }}>
          {%- else -%}
            {{ source_datum|raw }}
          {%- endif -%}
          {%- else -%}
          <{{ list_wrapper }}>{{ source_datum|striptags }}</{{ list_wrapper }}>
        {%- endif -%}
      {%- endif -%}
    {%- endif -%}
      </div>
    </div>
  {%- endif -%}
   
{%- endmacro html_output -%}
{# subproperty_mappings is {"@source_property": "rendered title"} #}
{%- macro html_output_with_subproperties(html_title, source_datum, subproperty_mappings, list_wrapper, markdown, rich) -%}
  {% set list_wrapper = list_wrapper|default("p") %}
 {% set markdown = markdown|default(false) %}
 {% set rich = rich|default(false) %}
  {% set values = [] %}
   {% if source_datum is iterable %}
     {% set value_by_source_indexed = [] %}
     {% set is_object = false %}
     {% for prop, prop_title in subproperty_mappings %}
     	 {% if source_datum[prop] is defined and source_datum[prop] is instanceof("scalar") %}
           {# means source_datum is an object, only accumulate scalars, never sub objects #}
           {% set is_object = true %}
           {% set value_by_source_indexed = value_by_source_indexed|merge([(prop_title) ~ " " ~ source_datum[prop] ]) %}
         {% endif %}  
     {% endfor %}   
     {% if not is_object %}
         {# means source_datum could be a numerically indexed array and value might be an object #}
         {% for value in source_datum %}
           {% if value is iterable %}
             {% set value_by_source = [] %}
             {% for prop, prop_title in subproperty_mappings %}
               {% if value[prop] is defined and value[prop] is instanceof("scalar")%}
                 {% set value_by_source = value_by_source|merge([(prop_title) ~ " " ~  value[prop] ]) %}
               {% endif %}  
             {% endfor %}
             {% if value_by_source is not empty %}
                   {% set values = values|merge([value_by_source]) %}
            {% endif %}
          {% endif %}
      {% endfor %}
    {% endif %}
     {% if value_by_source_indexed is not empty %}
         {% set values = values|merge([value_by_source_indexed]) %}
     {% endif %}
   {% endif %}
  
 
  {# -- Macro note: if markdown is selected no wrapper will be used -#}
  {%- if values and values|length > 0 -%}
  
  <div class="row border-1 mx-1 border-bottom">
    <div class="col-3 fw-light">
    {%- if html_title|length > 0 -%}
     <{{ list_wrapper }}>{{ html_title }}</{{ list_wrapper }}>
    {%- endif -%}
    </div>
    <div class="col-9 fw-light">
    {%- if values is iterable -%}
      {%- for source_data in values -%}
        {%- if markdown -%}
          {{ source_data|join("")|markdown_2_html }}
        {%- else -%}
          {%- if rich -%}
            <{{ list_wrapper }}>{{  source_data|join(" ")|raw }}</{{ list_wrapper }}>
          {%- else -%}
            <{{ list_wrapper }}>{{  source_data|join(" ")|striptags }}</{{ list_wrapper }}>
          {%- endif -%}
        {%- endif -%}
      {%- endfor -%}
      </div>
    </div>
  {%- endif -%}
  {%- endif -%}
{%- endmacro html_output_with_subproperties -%}

{%- macro html_output_list(html_title, source_datum, markdown, rich) -%}
 {% set markdown = markdown|default(false) %}
 {% set rich = rich|default(false) %}
  {# -- Macro note: if markdown is selected no wrapper will be used -#}
  {%- if source_datum and source_datum|length > 0 -%}
  <div class="row border-1 mx-1 border-bottom">
    <div class="col-3 fw-light">
    {%- if html_title|length > 0 -%}
      <p>{{ html_title }}</p>
    {%- endif -%}
    </div>
    <div class="col-9 fw-light">
      <ul>
    {%- if source_datum is iterable -%}
      {%- for source_data in source_datum -%}
        {%- if markdown -%}
          <li>{{ source_data|markdown_2_html }}</li>
        {%- elseif rich -%}
          <li>{{ source_data|raw }}</li>
        {%- else -%}
         <li>{{ source_data|striptags }}</li>
        {%- endif -%}
      {%- endfor -%}
    {%- else -%}
      {%- if markdown -%}
        <li>{{ source_datum|markdown_2_html }}</li>
       {%- elseif rich -%}  
         <li>{{ source_datum|raw }}</li>
      {%- else -%}
        <li>{{ source_datum|striptags }}</li>
      {%- endif -%}
    {%- endif -%}
      </ul>
    </div>
  </div>
  {%- endif -%}
{%- endmacro html_output_list -%}


{# Allison: internal search macros based off Diego's list output macro above;
added flag and formatting for internal search-based on value set within corresponding facet config;
one macro for simple non-LoD elements; second for LoD elements with URI and label values #}

{%- macro html_output_search(html_title, source_datum, search_facet) -%}
  {%- if source_datum and source_datum|length > 0 -%}
  <div class="row border-1 mx-1 border-bottom">
    <div class="col-3 fw-light">
    {%- if html_title|length > 0 -%}
      <p>{{ html_title }}</p>
    {%- endif -%}
    </div>
    <div class="col-9 fw-light">
      <ul>
    {%- if source_datum is iterable -%}
      {%- for source_data in source_datum -%}
        <li><a href="/search?search_api_fulltext=&f%5B0%5D={{ search_facet }}%3A{{ source_data|url_encode }}" target="_blank">{{ source_data }}</a></li>
      {%- endfor -%}
    {%- else -%}
      <li><a href="/search?search_api_fulltext=&f%5B0%5D={{ search_facet }}%3A{{ source_datum|url_encode }}" target="_blank">{{ source_datum }}</a></li>
    {%- endif -%}
      </ul>
    </div>
  </div>    
  {%- endif -%}
{%- endmacro html_output_search -%}


{# Use for LoD elements with URI and label values #}
{%- macro html_output_search_lod(html_title, source_datum, search_facet) -%}
  {%- if source_datum and source_datum|length > 0 -%}
  <div class="row border-1 mx-1 border-bottom">
    <div class="col-3 fw-light">  
    {%- if html_title|length > 0 -%}
      <p>{{ html_title }}</p>
    {%- endif -%}
    </div>
    <div class="col-9 fw-light">
      <ul>
    {%- for source_data in source_datum -%}
      <li><a href="/search?search_api_fulltext=&f%5B0%5D={{ search_facet }}%3A{{ source_data.label|url_encode }}" target="_blank">{{ source_data.label }}</a></li>
    {%- endfor -%}
      </ul>
    </div>
  </div>  
  {%- endif -%}
{%- endmacro html_output_search_lod -%}

{#- --- End Macros ---- -#}

